export interface Job_Status_ErrorResult {
  /** Debugging information. This property is internal to Google and should not be used. */
  debugInfo?: string | Computed<string>;
  /** Specifies where the error occurred, if present. */
  location?: string | Computed<string>;
  /** A human-readable description of the error. */
  message?: string | Computed<string>;
  /** A short error code that summarizes the error. */
  reason?: string | Computed<string>;
}

export interface Job_Status {
  /** Error details. */
  errorResult?: Job_Status_ErrorResult | Computed<Job_Status_ErrorResult>;
  /** Output only. The first errors encountered during the running of the job. The final message includes the number of errors that caused the process to stop. Errors here do not necessarily mean that the job has not completed or was unsuccessful. */
  errors?: Job_Status_ErrorResult[] | Computed<Job_Status_ErrorResult[]>;
  /** Output only. Running state of the job. Valid states include 'PENDING', 'RUNNING', and 'DONE'. */
  state?: string | Computed<string>;
}

